/* Somali Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ahmed": "most praised — Arabic", "Fatima": "A beloved feminine name, borne by the Prophet's daughter.", "Hassan": "handsome, good — Arabic", "Amina": "trustworthy — Arabic", "Abdi": "servant (of God) — Arabic abd", "Hodan": "A popular Somali feminine name.", "Darod": "One of the great Somali clan families; clan is identity.", "Hawiye": "One of the great Somali clan families.", "Isaaq": "One of the great Somali clan families of the north.", "Dir": "One of the great Somali clan families."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ahmed';
console.log(lookup(q));

